  addAvailabilityForParticipantOrganizationsOrgIdParticipantsParticipantIdAvailabilityPost,
  bulkCreateParticipantsOrganizationsOrgIdParticipantsPost,
  getParticipantsWithAvailabilityOrganizationsOrgIdParticipantsGet,
