    59→// ============= HELPER FUNCTIONS =============
    60→
    61→/**
    62→ * Converts a local datetime string from HTML datetime-local input
    63→ * to an ISO 8601 string with timezone offset
    64→ * @param localDateTime - DateTime string from datetime-local input (e.g., "2024-01-15T14:30")
    65→ * @param timezone - IANA timezone string (e.g., "America/New_York")
    66→ * @returns ISO 8601 datetime string with timezone offset (e.g., "2024-01-15T14:30:00-05:00")
    67→ */
    68→function convertLocalDateTimeToTimezone(
    69→  localDateTime: string,
    70→  timezone: string,
    71→): string {
    72→  if (!localDateTime) {
    73→    return "";
    74→  }
    75→
    76→  try {
    77→    // Parse the local datetime string
    78→    const [datePart, timePart] = localDateTime.split("T");
    79→    if (!datePart || !timePart) {
    80→      throw new Error("Invalid datetime format");
    81→    }
    82→
    83→    // Add seconds if not present
    84→    const timeWithSeconds = timePart.length === 5 ? `${timePart}:00` : timePart;
    85→
    86→    // Parse date components
    87→    const dateParts = datePart.split("-").map(Number);
    88→    const timeParts = timeWithSeconds.split(":").map(Number);
    89→
    90→    if (dateParts.length < 3 || timeParts.length < 2) {
    91→      throw new Error("Invalid date or time components");
    92→    }
    93→
    94→    const [year, month, day] = dateParts as [number, number, number];
    95→    const [hours, minutes, seconds = 0] = timeParts as [
    96→      number,
    97→      number,
    98→      number?,
    99→    ];
   100→
   101→    // Create a date object for the exact local time
   102→    // Then format it with the target timezone to get the offset
   103→    const localDate = new Date(
   104→      year,
   105→      month - 1,
   106→      day,
   107→      hours,
   108→      minutes,
   109→      seconds || 0,
   110→    );
   111→
   112→    // Use a formatter to extract the timezone offset
   113→    // We format the same moment in time to get the offset
   114→    const formatter = new Intl.DateTimeFormat("en-US", {
   115→      timeZone: timezone,
   116→      year: "numeric",
   117→      month: "2-digit",
   118→      day: "2-digit",
   119→      hour: "2-digit",
   120→      minute: "2-digit",
   121→      second: "2-digit",
   122→      timeZoneName: "longOffset", // This gives us the offset like "GMT-05:00"
   123→      hour12: false,
   124→    });
   125→
   126→    const formattedParts = formatter.formatToParts(localDate);
   127→    const timeZoneName =
   128→      formattedParts.find((part) => part.type === "timeZoneName")?.value || "";
   129→
   130→    // Extract offset from the timezone name (e.g., "GMT-05:00" -> "-05:00")
   131→    let offset = "Z"; // Default to UTC
   132→    if (timeZoneName.includes("GMT")) {
   133→      const match = /GMT([+-]\d{2}:\d{2})/.exec(timeZoneName);
   134→      if (match?.[1]) {
   135→        offset = match[1];
   136→      } else if (timeZoneName === "GMT") {
   137→        offset = "Z";
   138→      }
   139→    }
   140→
   141→    // Return the ISO 8601 format with the extracted offset
   142→    return `${datePart}T${timeWithSeconds}${offset}`;
   143→  } catch (error) {
   144→    console.error("Error converting datetime to ISO 8601:", error);
   145→    // Fallback: return with UTC indicator
   146→    const hasSeconds = localDateTime.split(":").length >= 3;
   147→    return hasSeconds ? `${localDateTime}Z` : `${localDateTime}:00Z`;
   148→  }
   149→}
