   212→async function getOrganizationWithResources(organizationId: string) {
   213→  const organization = await db.organization.findUnique({
   214→    where: { id: organizationId },
   215→    select: {
   216→      id: true,
   217→      agentName: true,
   218→      agentPhoneNumbers: {
   219→        select: { id: true },
   220→        take: 1,
   221→      },
   222→    },
   223→  });
   224→
   225→  if (!organization) {
   226→    throw new Error("Organization not found");
   227→  }
   228→
   229→  // Validate phone number exists
   230→  if (!organization.agentPhoneNumbers[0]?.id) {
   231→    throw new Error("No SMS phone number configured for organization");
   232→  }
   233→
   234→  // Find available mailbox
   235→  const { findLeastUsedMailbox } = await import(
   236→    "@/server/resource_access/mailbox-resource-accessor"
   237→  );
   238→  const since = new Date();
   239→  since.setDate(since.getDate() - 7);
   240→  const mailboxId = await findLeastUsedMailbox(organizationId, since);
   241→
   242→  if (!mailboxId) {
   243→    throw new Error("No email mailbox available for organization");
   244→  }
   245→
   246→  return { ...organization, mailboxId };
   247→}
   248→
   249→async function buildScheduleEventRequest(
   250→  organization: {
   251→    id: string;
   252→    agentName: string | null;
   253→    agentPhoneNumbers: { id: string }[];
   254→    mailboxId: string;
   255→  },
   256→  input: z.infer<typeof scheduleEventSchema>,
   257→  organizationId: string,
   258→  opportunityId?: string,
   259→) {
   260→  const { mailboxId, agentPhoneNumbers } = organization;
   261→  const smsContactMethodId = agentPhoneNumbers[0]?.id;
   262→
   263→  if (!smsContactMethodId) {
   264→    throw new Error("No SMS contact method available");
   265→  }
   266→
   267→  // Group participants by type
   268→  const participantsByType = input.participants.reduce(
   269→    (acc, p) => {
   270→      if (!acc[p.type]) {
   271→        acc[p.type] = [];
   272→      }
   273→      acc[p.type]!.push(p);
   274→      return acc;
   275→    },
   276→    {} as Record<string, typeof input.participants>,
   277→  );
   278→
   279→  // Build precedence levels (candidates first, then users)
   280→  const precedenceLevels = [];
   281→
   282→  const candidates = participantsByType.candidate;
   283→  if (candidates && candidates.length > 0) {
   284→    precedenceLevels.push({
   285→      role_description: "Candidate",
   286→      participants: candidates.map((p) =>
   287→        buildParticipantWithContact(
   288→          p,
   289→          mailboxId,
   290→          smsContactMethodId,
   291→          organizationId,
   292→          input.timezone,
   293→        ),
   294→      ),
   295→    });
   296→  }
   297→
   298→  const users = participantsByType.user;
   299→  if (users && users.length > 0) {
   300→    precedenceLevels.push({
   301→      role_description: "User",
   302→      participants: users.map((p) =>
   303→        buildParticipantWithContact(
   304→          p,
   305→          mailboxId,
   306→          smsContactMethodId,
   307→          organizationId,
   308→          input.timezone,
   309→        ),
   310→      ),
   311→    });
   312→  }
   313→
   314→  // Transform known availabilities to API format with per-participant timezone
   315→  const knownAvailabilities = input.knownAvailabilities
   316→    ? Object.entries(input.knownAvailabilities).reduce(
   317→        (acc, [participantId, participantAvailability]) => {
   318→          if (participantAvailability.slots.length > 0) {
   319→            // Use the participant's specific timezone for their availability
   320→            acc[participantId] = participantAvailability.slots.map((slot) => {
   321→              // Convert local datetime strings to ISO format with the participant's timezone
   322→              const startDateTime = convertLocalDateTimeToTimezone(
   323→                slot.startTime,
   324→                participantAvailability.timezone,
   325→              );
   326→              const endDateTime = convertLocalDateTimeToTimezone(
   327→                slot.endTime,
   328→                participantAvailability.timezone,
   329→              );
   330→
   331→              return {
   332→                start_time: startDateTime,
   333→                end_time: endDateTime,
   334→              };
   335→            });
   336→          }
   337→          return acc;
   338→        },
   339→        {} as Record<string, { start_time: string; end_time: string }[]>,
   340→      )
   341→    : undefined;
   342→
   343→  return {
   344→    agent: {
   345→      purplefish_id: organization.id,
   346→      name: organization.agentName || "Purplefish AI",
   347→    },
   348→    meeting_name: input.meetingName,
   349→    purpose: input.purpose,
   350→    duration_minutes: input.duration,
   351→    timeframe: input.timeframe,
   352→    participant_precedence_levels: precedenceLevels,
   353→    known_availabilities:
   354→      knownAvailabilities && Object.keys(knownAvailabilities).length > 0
   355→        ? knownAvailabilities
   356→        : undefined,
   357→    messaging_thread_id: uuidv4(),
