            client: messagingSdkClient,
            path: {
              org_id: organizationId,
            },
            query: {
              q: query,
            },
          });

        if (response.data) {
          apiParticipants = response.data.participants.slice(0, 10);
        }
      } catch (error) {
        console.error("Messaging API search failed:", error);
        warning =
          "Participant search service unavailable. Showing local results only.";
      }

      // Fetch local results
      const { searchCandidatesWithJobFilter } = await import(
        "@/server/resource_access/candidate-resource-accessor"
      );
      const [candidates, users] = await Promise.all([
        searchCandidatesWithJobFilter(organizationId, query),
        searchUsers(organizationId, query),
      ]);

      // Deduplicate and merge
      const phoneSet = new Set<string>();
      const emailSet = new Set<string>();
      const mergedParticipants: {
        id: string;
        firstName: string;
        lastName: string;
        email: string | null;
        phoneNumber: string | null;
        type?: "participant" | "candidate" | "user";
        source: "api" | "candidate" | "user";
        purplefishParticipantId: string;
        contactForAdditionalAvailability: boolean;
        opportunity?: {
          id: string;
          status: string;
          jobTitle: string;
        };
      }[] = [];

      // Helper to normalize phone numbers for comparison
      const normalizePhone = (phone: string | null | undefined) => {
        if (!phone) {
          return null;
        }
        return phone.replace(/\D/g, ""); // Remove non-digits
      };

      // Add API participants first (highest priority)
      apiParticipants.forEach((participant) => {
        const normalizedPhone = normalizePhone(participant.phone);

        if (normalizedPhone) {
          phoneSet.add(normalizedPhone);
        }
        if (participant.email) {
          emailSet.add(participant.email.toLowerCase());
        }

        mergedParticipants.push({
          id: participant.id,
          firstName: participant.first_name,
          lastName: participant.last_name,
          email: participant.email,
          phoneNumber: participant.phone,
          type: "participant" as const,
          source: "api" as const,
          purplefishParticipantId: participant.id,
          contactForAdditionalAvailability: true,
        });
      });

      // Add local candidates (skip duplicates by phone first, then email)
      candidates.forEach((candidate) => {
        const normalizedPhone = normalizePhone(candidate.phoneNumber);
        const isDuplicatePhone =
          normalizedPhone !== null && phoneSet.has(normalizedPhone);
        const isDuplicateEmail =
          candidate.email !== null &&
          emailSet.has(candidate.email.toLowerCase());

        if (!isDuplicatePhone && !isDuplicateEmail) {
          if (normalizedPhone) {
            phoneSet.add(normalizedPhone);
          }
          if (candidate.email) {
            emailSet.add(candidate.email.toLowerCase());
          }

          const participantData = candidateToParticipant(candidate);
          mergedParticipants.push({
            ...participantData,
            email: participantData.email ?? null,
            phoneNumber: participantData.phoneNumber ?? null,
            opportunity: candidate.opportunity,
            source: "candidate" as const,
          });
        }
      });

      // Add local users (skip duplicates by phone first, then email)
      users.forEach((user) => {
        const normalizedPhone = normalizePhone(user.phoneNumber);
        const isDuplicatePhone =
          normalizedPhone !== null && phoneSet.has(normalizedPhone);
        const isDuplicateEmail = emailSet.has(user.email.toLowerCase());

        if (!isDuplicatePhone && !isDuplicateEmail) {
          if (normalizedPhone) {
            phoneSet.add(normalizedPhone);
          }
          emailSet.add(user.email.toLowerCase());

          const userData = userToParticipant(user);
          mergedParticipants.push({
            ...userData,
            phoneNumber: userData.phoneNumber ?? null,
            source: "user" as const,
          });
        }
      });

      return {
        participants: mergedParticipants,
        warning,
      };
    }),

