      }),
    )
    .query(async ({ input }) => {
      const { organizationId, attemptId } = input;

      try {
        const response =
          await getSchedulingAttemptDetailSchedulingAttemptStatusSchedulingAttemptIdGet(
            {
              client: messagingSdkClient,
              path: {
                scheduling_attempt_id: attemptId,
              },
            },
          );

        if (!response.data) {
          throw new Error("Failed to fetch scheduling attempt detail");
        }

        // Verify organization access
        // eslint-disable-next-line @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment
        const responseData = response.data as any;
        // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
        if (responseData.organization_id !== organizationId) {
          throw new Error("Unauthorized access to this scheduling attempt");
        }

        return response.data;
      } catch (error) {
        console.error("Error fetching scheduling attempt detail:", error);
        throw new Error(
          "Failed to fetch scheduling attempt details. Please try again.",
        );
      }
    }),

  scheduleEvent: organizationMemberProcedure
    .input(scheduleEventSchema)
    .mutation(async ({ input }) => {
      const { organizationId, jobId, participants } = input;

      // Get organization details and validate resources
      const organization = await getOrganizationWithResources(organizationId);

      // If job is selected, find opportunities for all candidates
      // We'll use the first valid opportunity found as the primary one
      let opportunityId: string | undefined;
      if (jobId) {
        const candidates = participants.filter((p) => p.type === "candidate");

        if (candidates.length > 0) {
          // Try to find an opportunity for each candidate
          for (const candidate of candidates) {
            const { findOpportunityForCandidateAndJob } = await import(
