              );
              break; // Use the first valid opportunity found
            } else {
              console.warn(
                `No opportunity found for candidate ${candidate.id} and job ${jobId}`,
              );
            }
          }

          // Log if no opportunities were found for any candidate
          if (!opportunityId && candidates.length > 0) {
            console.warn(
              `No opportunities found for any of the ${candidates.length} candidates with job ${jobId}`,
            );
          }
        } else if (jobId) {
          console.info(
            `Job ${jobId} selected but no candidates in participant list`,
          );
        }
      }

      // Prepare the scheduling request with opportunity_id
      const request = await buildScheduleEventRequest(
        organization,
        input,
        organizationId,
        opportunityId,
      );

      // Send to messaging service using generated SDK
      try {
        const response = await scheduleEventAgentsScheduleEventPost({
          client: messagingSdkClient,
          body: request,
        });

        if (!response.data) {
          console.error("Failed to schedule event:", response.error);
          throw new Error("Failed to schedule event. Please try again.");
        }

        return { success: true, data: response.data };
      } catch (error) {
        console.error("Error scheduling event:", error);
        throw new Error("Failed to schedule event. Please try again.");
      }
    }),
